  let open = 0;
  for (const x of a) { counts.set(x, (counts.get(x) ?? 0) + 1); open++; }
  for (const x of b) {
    const left = counts.get(x) ?? 0;
    if (left === 0) return false;
    counts.set(x, left - 1);
    open--;
  }
  return open === 0;
}
