function majorityVote(items) {
  let candidate = null;
  let votes = 0;
  for (const item of items) {
    if (votes === 0) candidate = item;
    votes += item === candidate ? 1 : -1;
  }
  let count = 0;
  for (const item of items) if (item === candidate) count++;
  return count > items.length / 2 ? candidate : null;
}

