const methods = ["card", "ussd", "transfer", "ussd", "card", "cash"];

function topMethods(list) {
  const counts = new Map();
  for (const m of list) counts.set(m, (counts.get(m) ?? 0) + 1);
  let best = 0;
  let top = [];
  for (const [m, n] of counts) {
    if (n > best) {
      best = n;
      top = [m];
    } else if (n === best) {
      top.push(m);
    }
  }
  return top;
}

console.log(topMethods(methods));

